    print("=== Log Analysis ===")
    print()
    print("Entries by Level:")
    print()
    print("Component with Most Errors: N/A (0 errors)")
    print()
    print("Unique Error Messages:")
    print()
    print("Busiest Hour: 00:00 (0 entries)")
    exit(0)
}

let lines = content.components(separatedBy: "\n").filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }

var levelCounts: [String: Int] = [:]
var componentErrorCounts: [String: Int] = [:]
var errorMessages: Set<String> = []
var hourCounts: [Int: Int] = [:]

let pattern = "\\[\\d{4}-\\d{2}-\\d{2} (\\d{2}):\\d{2}:\\d{2}\\] (\\w+) \\(([^)]+)\\) - (.+)"
let regex = try! NSRegularExpression(pattern: pattern)

for line in lines {
    let range = NSRange(location: 0, length: (line as NSString).length)
    if let match = regex.firstMatch(in: line, range: range) {
        let hourStr = (line as NSString).substring(with: match.range(at: 1))
        let level = (line as NSString).substring(with: match.range(at: 2))
        let component = (line as NSString).substring(with: match.range(at: 3))
        let message = (line as NSString).substring(with: match.range(at: 4))

        let hourInt = Int(hourStr) ?? 0
        hourCounts[hourInt, default: 0] += 1
        levelCounts[level, default: 0] += 1

        if level == "ERROR" {
            componentErrorCounts[component, default: 0] += 1
            errorMessages.insert(message)
        }
    }
}

print("=== Log Analysis ===")
print()
print("Entries by Level:")
for level in levelCounts.keys.sorted() {
    print("  \(level): \(levelCounts[level]!)")
}
print()
if let top = componentErrorCounts.sorted(by: { ($0.value != $1.value) ? $0.value > $1.value : $0.key < $1.key }).first {
