import * as fs from 'fs';

function formatWithCommas(n: number, decimals: number): string {
    const fixed = n.toFixed(decimals);
    const neg = fixed.startsWith('-');
    const abs = neg ? fixed.substring(1) : fixed;
    const parts = abs.split('.');
    let intPart = parts[0];
    const decPart = parts.length > 1 ? parts[1] : '';

    let result = '';
    for (let i = intPart.length - 1, c = 0; i >= 0; i--) {
        result = intPart[i] + result;
        c++;
        if (c % 3 === 0 && i > 0) {
            result = ',' + result;
        }
    }

    let out = (neg ? '-' : '') + result;
    if (decimals > 0) {
        out += '.' + decPart;
    }
    return out;
}

const filePath = '<tmp>';
let csvContent = fs.readFileSync(filePath, 'utf-8');
if (csvContent.charCodeAt(0) === 0xFEFF) {
    csvContent = csvContent.substring(1);
}

const lines = csvContent.trim().split(/\r?\n/);
const data: { employee_id: string; name: string; department: string; salary: number; start_date: string; rating: string }[] = [];

for (let i = 1; i < lines.length; i++) {
    const cols = lines[i].split(',').map(s => s.trim());
    if (cols.length < 6) continue;
    data.push({
        employee_id: cols[0],
        name: cols[1],
        department: cols[2],
        salary: parseFloat(cols[3]),
        start_date: cols[4],
        rating: cols[5]
    });
}

const deptMap: Map<string, number[]> = new Map();
for (const emp of data) {
    if (!deptMap.has(emp.department)) {
        deptMap.set(emp.department, []);
    }
    deptMap.get(emp.department)!.push(emp.salary);
}

const sortedDepts = Array.from(deptMap.keys()).sort();

const out: string[] = [];
out.push('=== Salary Report ===');
out.push('');
out.push('Average Salary by Department:');
