use std::fs;
use std::collections::HashMap;

fn format_number_with_commas(n: i64) -> String {
    let s = n.to_string();
    let negative = s.starts_with('-');
    let digits: String = if negative { s[1..].to_string() } else { s };
    let bytes = digits.as_bytes();
    let len = bytes.len();
    let mut result = String::new();
    if negative {
        result.push('-');
    }
    for (i, b) in bytes.iter().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(*b as char);
    }
    result
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read file");
    let content = content.trim_start_matches('\u{feff}');

    let mut lines = content.lines();
    let _header = lines.next();

    let mut dept_salaries: HashMap<String, Vec<f64>> = HashMap::new();
    let mut highest_paid_name = String::new();
    let mut highest_paid_salary: f64 = f64::NEG_INFINITY;
    let mut total_budget: i64 = 0;

    for line in lines {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split(',').map(|s| s.trim()).collect();
        if fields.len() < 6 {
            continue;
        }
        let name = fields[1].to_string();
        let department = fields[2].to_string();
        let salary: f64 = fields[3].parse().unwrap_or(0.0);

        dept_salaries.entry(department).or_insert_with(Vec::new).push(salary);

        if salary > highest_paid_salary {
            highest_paid_salary = salary;
            highest_paid_name = name;
        }

        total_budget += salary as i64;
    }

    let mut depts: Vec<&String> = dept_salaries.keys().collect();
    depts.sort();

    println!("=== Salary Report ===");
    println!();
    println!("Average Salary by Department:");
    for dept in &depts {
        let salaries = &dept_salaries[*dept];
        let avg = salaries.iter().sum::<f64>() / salaries.len() as f64;
        let total_cents = (avg * 100.0).round() as i64;
        let int_part = total_cents / 100;
        let dec_part = (total_cents % 100).abs();
        let int_str = format_number_with_commas(int_part);
        println!("  {}: ${}.{:02}", dept, int_str, dec_part);
    }

    println!();
    let hp_int = highest_paid_salary.round() as i64;
    println!("Highest Paid: {} (${})", highest_paid_name, format_number_with_commas(hp_int));

    println!();
    println!("Departments with >2 employees:");
    for dept in &depts {
        let count = dept_salaries[*dept].len();
        if count > 2 {
            println!("  {} ({} employees)", dept, count);
        }
    }

    println!();
    println!("Total Budget: ${}", format_number_with_commas(total_budget));
}

