        adj[e["to"]].append((e["from"], e["weight"]))

    dist = {node: float('inf') for node in nodes}
    dist["A"] = 0

    visited = set()
    heap = [(0, "A")]

    while heap:
        d, u = heapq.heappop(heap)
        if u in visited:
