import * as fs from 'fs';

interface Edge {
    from: string;
    to: string;
    weight: number;
}

interface Graph {
    nodes: string[];
    edges: Edge[];
}

function dijkstra(graph: Graph, source: string): Map<string, number> {
    const dist = new Map<string, number>();
    const visited = new Set<string>();

    for (const node of graph.nodes) {
        dist.set(node, Infinity);
    }
    dist.set(source, 0);

    const adj = new Map<string, { node: string; weight: number }[]>();
    for (const node of graph.nodes) {
        adj.set(node, []);
    }
    for (const edge of graph.edges) {
        adj.get(edge.from)!.push({ node: edge.to, weight: edge.weight });
        adj.get(edge.to)!.push({ node: edge.from, weight: edge.weight });
    }

    while (visited.size < graph.nodes.length) {
        let minNode: string | null = null;
        let minDist = Infinity;
        for (const node of graph.nodes) {
            if (!visited.has(node) && dist.get(node)! < minDist) {
                minDist = dist.get(node)!;
                minNode = node;
            }
        }

        if (minNode === null) break;

        visited.add(minNode);

        const neighbors = adj.get(minNode)!;
        for (const { node, weight } of neighbors) {
            if (!visited.has(node)) {
                const newDist = dist.get(minNode)! + weight;
                if (newDist < dist.get(node)!) {
                    dist.set(node, newDist);
                }
            }
        }
    }

    return dist;
}

