import java.net.*;
import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) throws Exception {
        URL url = new URL("http://127.0.0.1:18923/api/products");
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("GET");
        conn.setConnectTimeout(10000);
        conn.setReadTimeout(10000);

        BufferedReader reader = new BufferedReader(new InputStreamReader(conn.getInputStream(), "UTF-8"));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            sb.append(line);
        }
        reader.close();
        conn.disconnect();

        String json = sb.toString();
        List<String[]> products = parseJsonArray(json);

        List<String[]> filtered = products.stream()
                .filter(p -> Double.parseDouble(p[1]) > 50.00)
                .sorted(Comparator.comparing(p -> p[0]))
                .collect(Collectors.toList());

        System.out.println("=== Filtered Products (price > $50.00) ===");
        System.out.println();
        for (String[] p : filtered) {
            System.out.printf("%s: $%.2f%n", p[0], Double.parseDouble(p[1]));
        }
        System.out.println();
        System.out.printf("Count: %d%n", filtered.size());
        double total = filtered.stream().mapToDouble(p -> Double.parseDouble(p[1])).sum();
        System.out.printf("Total: $%.2f%n", total);
    }

    static List<String[]> parseJsonArray(String json) {
        List<String[]> result = new ArrayList<>();
        json = json.trim();
        if (json.startsWith("[")) json = json.substring(1);
        if (json.endsWith("]")) json = json.substring(0, json.length() - 1);

        int i = 0;
        while (i < json.length()) {
            int start = json.indexOf('{', i);
            if (start == -1) break;
            int depth = 0;
            int end = start;
            while (end < json.length()) {
                char c = json.charAt(end);
                if (c == '{') depth++;
                else if (c == '}') {
                    depth--;
                    if (depth == 0) break;
                } else if (c == '"') {
                    end++;
                    while (end < json.length() && json.charAt(end) != '"') {
                        if (json.charAt(end) == '\\') end++;
                        end++;
                    }
                }
                end++;
            }
            String obj = json.substring(start, end + 1);
            String name = extractString(obj, "name");
            String price = extractNumber(obj, "price");
            result.add(new String[]{name, price});
            i = end + 1;
        }
        return result;
    }

    static String extractString(String obj, String key) {
        String pattern = "\"" + key + "\"";
        int idx = obj.indexOf(pattern);
        if (idx == -1) return "";
        idx += pattern.length();
        while (idx < obj.length() && obj.charAt(idx) != ':') idx++;
        idx++;
        while (idx < obj.length() && (obj.charAt(idx) == ' ' || obj.charAt(idx) == '\t')) idx++;
        if (idx >= obj.length() || obj.charAt(idx) != '"') return "";
        idx++;
        int start = idx;
        while (idx < obj.length()) {
            if (obj.charAt(idx) == '\\') {
                idx += 2;
                continue;
            }
            if (obj.charAt(idx) == '"') break;
            idx++;
        }
        return obj.substring(start, idx);
    }

    static String extractNumber(String obj, String key) {
        String pattern = "\"" + key + "\"";
        int idx = obj.indexOf(pattern);
        if (idx == -1) return "0";
        idx += pattern.length();
        while (idx < obj.length() && obj.charAt(idx) != ':') idx++;
        idx++;
        while (idx < obj.length() && (obj.charAt(idx) == ' ' || obj.charAt(idx) == '\t')) idx++;
        int start = idx;
        while (idx < obj.length() && (Character.isDigit(obj.charAt(idx)) || obj.charAt(idx) == '.' || obj.charAt(idx) == '-' || obj.charAt(idx) == '+')) {
            idx++;
        }
        String val = obj.substring(start, idx);
        return val.isEmpty() ? "0" : val;
    }
}

