use std::collections::HashMap;
use std::fs;

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read log file");

    let mut level_counts: HashMap<String, usize> = HashMap::new();
    let mut error_component_counts: HashMap<String, usize> = HashMap::new();
    let mut error_messages: Vec<String> = Vec::new();
    let mut hour_counts: HashMap<String, usize> = HashMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        let start = match line.find('[') {
            Some(s) => s,
            None => continue,
        };
        let end = match line.find(']') {
            Some(e) => e,
            None => continue,
        };
        if start != 0 || end <= start {
            continue;
        }

        let timestamp = &line[start + 1..end];
        let rest = line[end + 1..].trim_start();

        // Extract hour
        if timestamp.len() >= 13 {
            let hour = &timestamp[11..13];
            let hour_key = format!("{}:00", hour);
            *hour_counts.entry(hour_key).or_insert(0) += 1;
        }

        // Parse LEVEL (component) - message
        let paren_start = match rest.find('(') {
            Some(p) => p,
            None => continue,
        };
        let paren_end = match rest.find(')') {
            Some(p) => p,
            None => continue,
        };
        if paren_end <= paren_start {
            continue;
        }

        let level = rest[..paren_start].trim().to_string();
        let component = rest[paren_start + 1..paren_end].to_string();

        let message = match rest.find(" - ") {
            Some(pos) => rest[pos + 3..].to_string(),
            None => String::new(),
        };

        *level_counts.entry(level.clone()).or_insert(0) += 1;

        if level == "ERROR" {
            *error_component_counts.entry(component).or_insert(0) += 1;
            error_messages.push(message);
        }
    }

    println!("=== Log Analysis ===");
    println!();

    println!("Entries by Level:");
    let mut levels: Vec<&String> = level_counts.keys().collect();
    levels.sort();
    for level in &levels {
        println!("  {}: {}", level, level_counts[level]);
    }
    println!();

    let mut comps: Vec<(&String, &usize)> = error_component_counts.iter().collect();
    comps.sort_by(|a, b| b.1.cmp(a.1).then(a.0.cmp(b.0)));
    if let Some((comp, count)) = comps.first() {
        println!("Component with Most Errors: {} ({} errors)", comp, count);
    }
    println!();

    println!("Unique Error Messages:");
    error_messages.sort();
    error_messages.dedup();
    for msg in &error_messages {
        println!("  - {}", msg);
    }
    println!();

    let mut hours: Vec<(&String, &usize)> = hour_counts.iter().collect();
    hours.sort_by(|a, b| b.1.cmp(a.1).then(a.0.cmp(b.0)));
    if let Some((hour, count)) = hours.first() {
        println!("Busiest Hour: {} ({} entries)", hour, count);
    }
}

