static int pair_cmp(const void *a, const void *b) {
    const json_pair *pa = (const json_pair *)a;
    const json_pair *pb = (const json_pair *)b;
    return strcmp(pa->key, pb->key);
}

static void sort_object(json_value *v) {
    if (v->type != JSON_OBJECT) return;
    qsort(v->object.pairs, v->object.count, sizeof(json_pair), pair_cmp);
    for (size_t i = 0; i < v->object.count; i++) {
        sort_object(v->object.pairs[i].value);
