fn decode_chunked(data: &str) -> String {
    let mut result = String::new();
    let mut pos = 0;
    let bytes = data.as_bytes();
    while pos < bytes.len() {
        // Find end of chunk size line
        let mut line_end = pos;
        while line_end < bytes.len() && bytes[line_end] != b'\n' {
            line_end += 1;
        }
        if line_end >= bytes.len() {
            break;
        }
        line_end += 1; // skip \n
        let size_str = std::str::from_utf8(&bytes[pos..line_end]).unwrap_or("0").trim();
        let size = usize::from_str_radix(size_str, 16).unwrap_or(0);
        if size == 0 {
            break;
        }
        let chunk_start = line_end;
        let chunk_end = (chunk_start + size).min(bytes.len());
        if let Ok(s) = std::str::from_utf8(&bytes[chunk_start..chunk_end]) {
            result.push_str(s);
        }
        pos = chunk_end;
        // Skip the \r\n after chunk data
        if pos + 1 < bytes.len() && bytes[pos] == b'\r' && bytes[pos + 1] == b'\n' {
            pos += 2;
        } else if pos < bytes.len() && bytes[pos] == b'\n' {
            pos += 1;
        }
    }
    result
}

