    public static void main(String[] args) throws Exception {
        Path root = Paths.get("<tmp>");

        Map<String, List<String[]>> extMap = new TreeMap<>();

        walk(root, root, extMap);

        for (List<String[]> files : extMap.values()) {
            files.sort((a, b) -> a[0].compareTo(b[0]));
        }

        long totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;

        for (List<String[]> files : extMap.values()) {
            for (String[] f : files) {
                totalFiles++;
                totalLines += Long.parseLong(f[1]);
                totalChars += Long.parseLong(f[2]);
            }
        }

        System.out.println("=== File Tree Analysis ===");
        System.out.println();

        for (Map.Entry<String, List<String[]>> entry : extMap.entrySet()) {
            String ext = entry.getKey();
            List<String[]> files = entry.getValue();

            long linesSum = 0;
            long charsSum = 0;
            for (String[] f : files) {
                linesSum += Long.parseLong(f[1]);
                charsSum += Long.parseLong(f[2]);
            }

            System.out.println("Extension: " + ext);
            System.out.println("  Files: " + files.size());
            System.out.println("  Total Lines: " + linesSum);
            System.out.println("  Total Characters: " + charsSum);

            for (String[] f : files) {
                System.out.println("    " + f[0] + ": " + f[1] + " lines, " + f[2] + " chars");
            }
        }

        System.out.println();
        System.out.println("Total: " + totalFiles + " files, " + totalLines + " lines, " + totalChars + " characters");
    }

    static void walk(Path dir, Path root, Map<String, List<String[]>> extMap) throws IOException {
        File[] children = dir.toFile().listFiles();
        if (children == null) return;

        for (File child : children) {
            Path childPath = child.toPath();

            if (Files.isSymbolicLink(childPath)) {
                continue;
            }

            if (Files.isDirectory(childPath)) {
                walk(childPath, root, extMap);
            } else if (Files.isRegularFile(childPath)) {
                long lines = countLines(childPath);
                long chars = Files.size(childPath);

                String relativePath = root.relativize(childPath).toString().replace(File.separatorChar, '/');

                String name = child.getName();
                String ext = "";
                int dotIdx = name.lastIndexOf('.');
                if (dotIdx > 0) {
                    ext = name.substring(dotIdx);
                }

                extMap.computeIfAbsent(ext, k -> new ArrayList<>()).add(new String[]{relativePath, String.valueOf(lines), String.valueOf(chars)});
            }
        }
    }

    static long countLines(Path path) throws IOException {
        try (BufferedReader reader = Files.newBufferedReader(path)) {
            long count = 0;
            while (reader.readLine() != null) {
                count++;
            }
            return count;
        }
    }
