    static void printMatrix(int[][] m) {
        for (int[] row : m) {
            System.out.print("  ");
            for (int i = 0; i < row.length; i++) {
                if (i > 0) System.out.print(" ");
                System.out.printf("%4d", row[i]);
            }
            System.out.println();
        }
    }

    static int determinant(int[][] m, int n) {
        if (n == 1) return m[0][0];
        if (n == 2) return m[0][0] * m[1][1] - m[0][1] * m[1][0];

        int det = 0;
        for (int j = 0; j < n; j++) {
            int[][] minor = new int[n - 1][n - 1];
            for (int i = 1; i < n; i++) {
                int col = 0;
                for (int k = 0; k < n; k++) {
                    if (k == j) continue;
                    minor[i - 1][col++] = m[i][k];
                }
            }
            int sign = (j % 2 == 0) ? 1 : -1;
            det += sign * m[0][j] * determinant(minor, n - 1);
        }
        return det;
    }
