static char *parse_string(char **p) {
    if (**p != '"') return NULL;
    (*p)++;
    char *start = *p;
    while (**p && **p != '"') {
        if (**p == '\\' && (*p)[1]) {
            (*p)++;
        }
        (*p)++;
    }
    if (**p == '"') {
        int len = (int)(*p - start);
        char *s = (char *)malloc(len + 1);
        if (s) {
            memcpy(s, start, len);
            s[len] = '\0';
            (*p)++;
        }
        return s;
    }
    return NULL;
