    if (a->count >= a->capacity) {
        a->capacity = a->capacity ? a->capacity * 2 : 128;
        a->items = (char **)realloc(a->items, (size_t)a->capacity * sizeof(char *));
        if (!a->items) { fprintf(stderr, "OOM\n"); exit(1); }
    }
    a->items[a->count] = strdup(s);
    if (!a->items[a->count]) { fprintf(stderr, "OOM\n"); exit(1); }
    a->count++;
}

static void sa_free(StrArray *a) {
    for (int i = 0; i < a->count; i++) free(a->items[i]);
    free(a->items);
    a->items = NULL;
    a->count = 0;
    a->capacity = 0;
}

