        qsort(error_components.items, (size_t)error_components.count, sizeof(char *), cmp_str);
    if (error_messages.count > 1)
        qsort(error_messages.items, (size_t)error_messages.count, sizeof(char *), cmp_str);

    /* Output */
    printf("=== Log Analysis ===\n");
    printf("\n");

    printf("Entries by Level:\n");
    for (int i = 0; i < levels.count; i++) {
        int cnt = 1;
        while (i + 1 < levels.count && strcmp(levels.items[i], levels.items[i + 1]) == 0) {
            i++;
            cnt++;
        }
        printf("  %s: %d\n", levels.items[i], cnt);
    }

    printf("\n");

    if (error_components.count > 0) {
        int best_idx = 0;
        int best_count = 1;
        for (int i = 0; i < error_components.count; i++) {
            int cnt = 1;
            while (i + 1 < error_components.count && strcmp(error_components.items[i], error_components.items[i + 1]) == 0) {
                i++;
                cnt++;
            }
            if (cnt > best_count) {
                best_count = cnt;
                best_idx = i;
            }
        }
        printf("Component with Most Errors: %s (%d errors)\n", error_components.items[best_idx], best_count);
    } else {
        printf("Component with Most Errors: N/A (0 errors)\n");
    }

    printf("\n");

    printf("Unique Error Messages:\n");
    for (int i = 0; i < error_messages.count; i++) {
        if (i > 0 && strcmp(error_messages.items[i], error_messages.items[i - 1]) == 0)
            continue;
        printf("  - %s\n", error_messages.items[i]);
    }

    printf("\n");

    int best_hour = 0;
    int best_hour_count = 0;
    for (int h = 0; h < 24; h++) {
        if (hour_counts[h] > best_hour_count) {
            best_hour_count = hour_counts[h];
            best_hour = h;
        }
    }
    printf("Busiest Hour: %02d:00 (%d entries)\n", best_hour, best_hour_count);

    sa_free(&levels);
    sa_free(&error_components);
    sa_free(&error_messages);

