static void format_comma_long(long val, char *buf, size_t bufsize) {
    char tmp[32];
    sprintf(tmp, "%ld", val);
    int len = (int)strlen(tmp);
    int pos = 0;
    int first = (len % 3 == 0) ? 3 : (len % 3);
    for (int i = 0; i < first && i < len; i++) {
        if (pos + 1 < (int)bufsize) buf[pos++] = tmp[i];
    }
    for (int i = first; i < len; i++) {
        if ((i - first) % 3 == 0) {
            if (pos + 1 < (int)bufsize) buf[pos++] = ',';
        }
        if (pos + 1 < (int)bufsize) buf[pos++] = tmp[i];
    }
    buf[pos] = '\0';
}

static void format_comma_double(double val, char *buf, size_t bufsize) {
    long intpart = (long)floor(val);
    int decimals = (int)lround((val - (double)intpart) * 100.0);
    if (decimals == 100) { intpart++; decimals = 0; }
    if (decimals == -100) { intpart--; decimals = 0; }
    if (decimals < 0) decimals = -decimals;
    char intbuf[32];
    format_comma_long(intpart, intbuf, sizeof(intbuf));
    snprintf(buf, bufsize, "%s.%02d", intbuf, decimals);
}

