    let mut total_lines: u64 = 0;
    let mut total_chars: u64 = 0;

    for (ext, file_list) in &groups {
        let n_files = file_list.len() as u64;
        let n_lines: u64 = file_list.iter().map(|f| f.1).sum();
        let n_chars: u64 = file_list.iter().map(|f| f.2).sum();

        total_files += n_files;
        total_lines += n_lines;
        total_chars += n_chars;

