import Foundation

let baseDir = "<tmp>"
let fileManager = FileManager.default
let baseURL = URL(fileURLWithPath: baseDir)

struct FileInfo {
    let relativePath: String
    let lines: Int
    let chars: Int
}

var filesByExt: [String: [FileInfo]] = [:]
var visited: Set<URL> = []

func walkDirectory(_ url: URL, relativePath: String) {
    let resolvedURL = url.standardizedFileURL
    if visited.contains(resolvedURL) { return }
    visited.insert(resolvedURL)

    let keys: [URLResourceKey] = [.isRegularFileKey, .isSymbolicLinkKey]
    guard let contents = try? fileManager.contentsOfDirectory(at: url, includingPropertiesForKeys: keys, options: []) else { return }

    for item in contents {
        let itemRelPath = relativePath.isEmpty ? item.lastPathComponent : relativePath + "/" + item.lastPathComponent

        let values = try? item.resourceValues(forKeys: Set(keys))
        let isSymlink = values?.isSymbolicLink ?? false

        if isSymlink {
            continue
        }

        let isRegularFile = values?.isRegularFile ?? false

        if isRegularFile {
            let data = (try? Data(contentsOf: item)) ?? Data()
            let chars = data.count
            let content = String(data: data, encoding: .utf8) ?? ""

            let lines: Int
            if data.isEmpty {
                lines = 0
            } else {
                let newlineCount = content.reduce(0) { $0 + ($1 == "\n" ? 1 : 0) }
                if content.hasSuffix("\n") {
                    lines = newlineCount
                } else {
                    lines = newlineCount + 1
                }
            }

            let ext = item.pathExtension
            let extKey = ext.isEmpty ? "(no extension)" : "." + ext

            let info = FileInfo(relativePath: itemRelPath, lines: lines, chars: chars)
            filesByExt[extKey, default: []].append(info)
        } else {
            walkDirectory(item, relativePath: itemRelPath)
        }
    }
}

