    totalLines += extLines
    totalChars += extChars

    print("Extension: \(ext)")
    print("  Files: \(fileCount)")
    print("  Total Lines: \(extLines)")
    print("  Total Characters: \(extChars)")
    for f in extFiles {
        print("    \(f.relativePath): \(f.lines) lines, \(f.chars) chars")
    }
}

