        }
        '[' => {
            *pos += 1;
            let mut items = Vec::new();
            skip_whitespace(s, pos);
            if *pos < s.len() && s.as_bytes()[*pos] as char == ']' {
                *pos += 1;
                return Json::Arr(items);
