import * as fs from 'fs';
import * as path from 'path';

const ROOT = '<tmp>';

interface FileStats {
  relativePath: string;
  lines: number;
  chars: number;
}

function getExtension(filename: string): string {
  const lastDot = filename.lastIndexOf('.');
  if (lastDot <= 0) return '';
  return filename.substring(lastDot);
}

function getFileStats(filePath: string): { lines: number; chars: number } {
  const content: Buffer = fs.readFileSync(filePath);
  const chars: number = content.length;
  if (content.length === 0) return { lines: 0, chars: 0 };
  let newlines = 0;
  for (let i = 0; i < content.length; i++) {
    if (content[i] === 10) newlines++;
  }
  let lines = newlines;
  if (content[content.length - 1] !== 10) lines++;
  return { lines, chars };
}

function walkDir(dir: string, root: string, visited: Set<string>): Map<string, FileStats[]> {
  const result: Map<string, FileStats[]> = new Map();

  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch (e) {
    return result;
  }

  for (const entry of entries) {
    const fullPath: string = path.join(dir, entry.name);

    if (entry.isSymbolicLink()) {
      continue;
    }

    if (entry.isDirectory()) {
      let resolved: string;
      try {
        resolved = fs.realpathSync(fullPath);
      } catch (e) {
        continue;
      }
      if (visited.has(resolved)) continue;
      visited.add(resolved);

      const subResults = walkDir(fullPath, root, visited);
      for (const [ext, files] of subResults) {
        if (!result.has(ext)) result.set(ext, []);
        result.get(ext)!.push(...files);
      }
    } else if (entry.isFile()) {
      const relativePath: string = path.relative(root, fullPath).split(path.sep).join('/');
      const ext: string = getExtension(entry.name);
      const stats = getFileStats(fullPath);

      if (!result.has(ext)) result.set(ext, []);
      result.get(ext)!.push({ relativePath, lines: stats.lines, chars: stats.chars });
    }
  }

  return result;
}

const visited = new Set<string>();
try {
  visited.add(fs.realpathSync(ROOT));
} catch (e) {
  process.stdout.write('=== File Tree Analysis ===\n\n\nTotal: 0 files, 0 lines, 0 characters\n');
  process.exit(0);
}

const grouped = walkDir(ROOT, ROOT, visited);

const sortedExts: string[] = Array.from(grouped.keys()).sort();

for (const ext of sortedExts) {
  grouped.get(ext)!.sort((a, b) => a.relativePath < b.relativePath ? -1 : a.relativePath > b.relativePath ? 1 : 0);
}

let totalFiles = 0;
let totalLines = 0;
